css:
/* ---------- 11 · footer ---------- */
.seo-footer { border-top: 1px solid rgba(var(--hair),.09); padding: 30px 4px 10px; }
.seo-footer__grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.seo-footer__col { display: flex; flex-direction: column; gap: 7px; font-size: 13px; color: var(--ink-2); }
.seo-footer__head { font-size: 10.5px; font-weight: 800; text-transform: uppercase; letter-spacing: .08em; color: var(--ink-3); margin-bottom: 3px; }
.seo-footer__row { display: flex; justify-content: space-between; gap: 14px; max-width: 220px; }
.seo-footer__link { color: var(--ink-2); text-decoration: none; }
.seo-footer__link:hover { color: var(--accent); }
.seo-footer__muted { color: var(--ink-3); font-size: 12px; line-height: 1.5; }
.seo-footer__base {
  display: flex; justify-content: space-between; align-items: center; gap: 14px; flex-wrap: wrap;
  margin-top: 26px; padding-top: 16px; border-top: 1px solid rgba(var(--hair),.07);
  font-weight: 800; font-size: 14px;
}
